using System;
using UnityEngine;
using Pvp.Map;
using Pvp.Traffic;
using Pvp.Competition;
namespace Pvp.Tests.EditMode {
public static class PvpCompetitionTests {
 static int checks;static void Check(bool ok,string reason){checks++;if(!ok)throw new Exception("PVP_COMPETITION: "+reason);}
 static PvpMapRuntime map;
 static PvpPassengerAuthority Create(int seconds=20,int grace=1){var settings=new PvpSessionConfig{MatchDurationSeconds=seconds,FinishGraceSeconds=grace,PlayerCount=2,RulesVersion="competition-tests"}.Freeze(Guid.NewGuid().ToString("N"),map.MapHash);return new PvpPassengerAuthority(map,settings,10,7);}
 static void Enqueue(PvpPassengerAuthority a,int player,PvpPassengerCommand command){command.MatchId=a.Round.Settings.MatchId;a.Enqueue(player,command);}
 static PvpPassengerCommand Command(string id,string passenger,int kind,int revision){return new PvpPassengerCommand{RequestId=id,PassengerId=passenger,Kind=kind,Revision=revision};}
 static void Hold(PvpPassengerAuthority a,int player,int stop){var pose=a.AtStop(stop);for(int i=0;i<10;i++){int tick=a.Round.Tick+1;pose.Tick=tick;a.ObserveVehicle(player,pose,true);a.Advance(tick);}}
 static PvpPassengerAuthority Race(bool reverse,out int owner){var a=Create();a.Advance(10);for(int t=11;t<=20;t++){var pose=a.AtStop(0);pose.Tick=t;a.ObserveVehicle(0,pose,true);a.ObserveVehicle(1,pose,true);a.Advance(t);}for(int i=0;i<2;i++){int player=reverse?1-i:i;Enqueue(a,player,Command("claim-"+player,"p-1",1,1));}a.Advance(21);owner=a.Passenger("p-1").Owner;Check(owner>=0&&a.TripFor(1-owner)==null,"single owner and empty loser");return a;}
 public static void Run(){
  var emptyJson=JsonUtility.ToJson(new Pvp.Network.PvpSharedWorld());var empty=JsonUtility.FromJson<Pvp.Network.PvpSharedWorld>(emptyJson);Debug.Log("PVP_EMPTY_WORLD_JSON "+emptyJson+" decodedMatchNull="+(empty.Match==null));Check(empty.Normalize().Match==null,"unstarted shared world must remain without a match");PvpReconnectTests.Run();checks=0;var definition=PvpMapDefinition.CreateDefault();try{map=new PvpMapRuntime(definition);
  Check(PvpTrafficAuthority.At(0).Phase==0&&PvpTrafficAuthority.At(249).NextChangeTick==250&&PvpTrafficAuthority.At(250).Phase==1&&PvpTrafficAuthority.At(500).Phase==0,"shared signal exact boundaries");
  Check(PvpTrafficAuthority.At(0).ObstacleXmm==-5000&&PvpTrafficAuthority.At(200).ObstacleXmm==5000&&PvpTrafficAuthority.At(400).ObstacleXmm==-5000,"authority obstacle deterministic cycle");
  var blocked=new Pvp.Network.PvpNetworkMotor(map,0,true);var blockState=blocked.Capture();blockState.Edge=16;blockState.Fraction=.5f;blockState.State.Position=Vector3.zero;blockState.State.Speed=1;blockState.State.YawDegrees=0;blocked.Restore(blockState);blocked.Step(new Pvp.Driving.PvpVehicleInput(1,0,0),100);Check(blocked.Capture().State.Position==Vector3.zero&&blocked.Capture().State.Speed==0,"authority motor stopped by shared obstacle");
  Check(PvpTrafficAuthority.Blocks(new Vector3(-2,0,0),new Vector3(2,0,0),100)&&!PvpTrafficAuthority.Blocks(new Vector3(50,0,0),new Vector3(51,0,0),100),"swept obstacle contact");
  int owner,other;var a=Race(false,out owner);var b=Race(true,out other);Check(owner==other,"same-tick order independent of packet arrival");string trip=a.TripFor(owner).TripId;Enqueue(a,owner,Command("claim-"+owner,"p-1",1,1));a.Advance(22);Check(a.LastResponse(owner).Accepted&&a.TripFor(owner).TripId==trip,"retry returns same trip");
  Enqueue(a,1-owner,Command("remote","p-2",1,1));a.Advance(23);Check(!a.LastResponse(1-owner).Accepted,"remote pickup rejected");
  var c=Create();c.Advance(10);var bad=c.AtStop(0);bad.State.YawDegrees+=180;for(int t=11;t<=20;t++){bad.Tick=t;c.ObserveVehicle(0,bad,true);c.Advance(t);}Enqueue(c,0,Command("wrong-way","p-1",1,1));c.Advance(21);Check(!c.LastResponse(0).Accepted,"opposite stop direction rejected");
  var shortHold=Create();shortHold.Advance(10);var shortPose=shortHold.AtStop(0);shortPose.Tick=11;for(int i=0;i<20;i++)shortHold.ObserveVehicle(0,shortPose,true);Enqueue(shortHold,0,Command("short","p-1",1,1));shortHold.Advance(12);Check(!shortHold.LastResponse(0).Accepted,"duplicate observation cannot manufacture stop duration");
  Hold(a,owner,1);a.Ledger.BeforeCompletionCommit=()=>{throw new InvalidOperationException("injected precommit");};Enqueue(a,owner,Command("complete-fail","p-1",2,2));a.Advance(a.Round.Tick+1);Check(a.Passenger("p-1").Status==PvpPassengerStatus.Onboard&&a.Ledger.Sequence==0&&a.Ledger.Read(owner).Completed==0,"completion failure atomic");a.Ledger.BeforeCompletionCommit=null;
  Enqueue(a,owner,Command("complete-ok","p-1",2,2));a.Advance(a.Round.Tick+1);int sequence=a.Ledger.Sequence;long score=a.Ledger.Read(owner).Score;Enqueue(a,owner,Command("complete-ok","p-1",2,2));Enqueue(a,owner,Command("complete-repeat","p-1",2,2));a.Advance(a.Round.Tick+1);Check(a.Passenger("p-1").Status==PvpPassengerStatus.Completed&&a.Ledger.Sequence==sequence&&a.Ledger.Read(owner).Score==score&&a.Ledger.Read(owner).Completed==1,"completion replay idempotent");
  Enqueue(a,1-owner,Command("reopen","p-1",1,3));a.Advance(a.Round.Tick+1);Check(!a.LastResponse(1-owner).Accepted,"terminal passenger cannot reopen");
  var left=Create();left.Advance(10);Hold(left,1,0);Enqueue(left,1,Command("pick-left","p-1",1,1));left.Advance(left.Round.Tick+1);left.Round.Leave(1);left.Advance(left.Round.Tick+1);Check(left.Passenger("p-1").Status==PvpPassengerStatus.Cancelled&&left.Ledger.Sequence==0,"withdrawal cancels unfinished fare without payment");
  var boundary=Create(2,1);boundary.Advance(10);Hold(boundary,0,0);Enqueue(boundary,0,Command("pickup-end","p-1",1,1));boundary.Advance(boundary.Round.MainEndTick);Check(!boundary.LastResponse(0).Accepted&&boundary.Passenger("p-1").Status==PvpPassengerStatus.Expired,"main-end equality rejects pickup");
  var closing=Create(2,1);closing.Advance(10);Hold(closing,0,0);Enqueue(closing,0,Command("pick","p-1",1,1));closing.Advance(21);Hold(closing,0,1);Enqueue(closing,0,Command("final-equality","p-1",2,2));closing.Advance(closing.Round.FinalEndTick);Check(!closing.LastResponse(0).Accepted&&closing.Ledger.Sequence==0&&closing.Round.Phase==PvpRoundPhase.Results,"final-end equality rejects completion");
  var ledger=new PvpScoreLedger();ledger.ApplyIncident(0,"line",1,2,1);ledger.Complete(0,"t1",10000,2);Check(ledger.Read(0).Score==98,"empty-car incident removes first safety bonus");ledger.ApplyIncident(0,"line",2,7,3);ledger.Complete(0,"t2",10000,4);Check(ledger.Read(0).Score==203&&ledger.Read(0).Bonus==10&&ledger.Read(0).Penalty==7,"old incident upgrade only delta; new segment stays safe");ledger.ApplyIncident(0,"line",2,999,5);ledger.ApplyIncident(0,"line",3,3,5);Check(ledger.Read(0).Score==203,"duplicate/lower incident no change");
  var scoped=Create();scoped.Advance(10);Hold(scoped,0,0);var foreign=Command("foreign-game","p-1",1,1);foreign.MatchId="old-round";scoped.Enqueue(0,foreign);scoped.Advance(scoped.Round.Tick+1);Check(!scoped.LastResponse(0).Accepted&&scoped.TripFor(0)==null,"old match request cannot claim current passenger");
  Enqueue(scoped,0,Command("foreign-game","p-1",1,1));scoped.Advance(scoped.Round.Tick+1);Check(scoped.LastResponse(0).Accepted,"request cache scoped by match identity");
  var zeroIncident=new PvpScoreLedger();zeroIncident.ApplyIncident(0,"unconfirmed",1,0,1);zeroIncident.Complete(0,"before-positive",10000,2);zeroIncident.ApplyIncident(0,"unconfirmed",2,7,3);zeroIncident.Complete(0,"after-positive",10000,4);Check(zeroIncident.Read(0).Score==203,"first positive penalty anchors current safety segment");
  var rounding=new PvpScoreLedger();rounding.Complete(0,"small1",150,1);rounding.Complete(0,"small2",150,2);Check(rounding.Read(0).FarePoints==2,"per-trip flooring");
  var negative=new PvpScoreLedger();negative.ApplyIncident(1,"negative",1,12,1);negative.Complete(1,"real",500,2);var rank=negative.BuildResult(true,true);Check(rank[1].Score==-7&&rank[1].Rank==1&&!rank[0].Eligible,"no-delivery zero cannot beat negative delivery");
  var tie=new PvpScoreLedger();tie.Complete(0,"a",10000,1);tie.Complete(1,"b",10000,1);var ties=tie.BuildResult(true,true);Check(ties[0].Rank==1&&ties[1].Rank==1,"joint winners");
  var overflow=new PvpScoreLedger();bool rejected=false;try{overflow.Complete(0,"overflow",long.MaxValue,1,1,long.MaxValue,1);}catch(OverflowException){rejected=true;}Check(rejected&&overflow.Sequence==0&&overflow.Read(0).Score==0,"overflow rejected before commit");
  var freeze=Create(2,1).Round;freeze.Disconnect(1,10,freeze.FinalEndTick-10+1);freeze.Advance(freeze.FinalEndTick);freeze.Finish();freeze.Advance(freeze.FinalEndTick+100);freeze.Leave(1);Check(freeze.Eligible(1),"eligibility frozen despite later expiry/leave");
  var expiry=Create(2,1).Round;expiry.Disconnect(1,10,expiry.FinalEndTick-10);expiry.Advance(expiry.FinalEndTick);Check(!expiry.Eligible(1),"expiry equal final precedes eligibility freeze");
  var countdown=Create().Round;countdown.Disconnect(1,0,50);Check(countdown.Phase==PvpRoundPhase.Lobby,"pre-start disconnect cancels countdown");
  var restored=JsonUtility.FromJson<PvpCompetitionSnapshot>(JsonUtility.ToJson(a.Snapshot()));Check(restored.LedgerSequence==sequence&&restored.Scores[owner].Score==score,"network snapshot aggregate roundtrip");long sum=0;foreach(var e in a.Ledger.Entries)if(e.Player==owner)sum=checked(sum+e.Amount);Check(sum==score,"ledger recomputation matches snapshot");
  Check(PvpPassengerAuthority.QuoteFare(10000)==2000&&PvpPassengerAuthority.QuoteFare(10001)==3000,"fare distance-step ceiling");
  Debug.Log("PVP_COMPETITION_MODEL_OK checks="+checks+" traffic/race/geometry/boundaries/atomic/replay/incident/safety/negative/rank/overflow/snapshot");
  }finally{UnityEngine.Object.DestroyImmediate(definition);}
 }
}}
